// Hand-rolled SPL Token transfer builder + Associated Token Account (ATA) PDA derivation.
// PURE module — no network. Byte-exact against @solana/web3.js v1 + @solana/spl-token v0.4.9
// (golden vectors in __tests__/solana-spl.test.ts, generated by .dev/sol-poc/09-spl-golden.mjs).
//
// Builds the canonical v2 USDC payment message: {Memo(ix0), Token.transferChecked(ix1)} against a
// recent blockhash. The Token Program instruction discriminator is a SINGLE BYTE u8 (unlike the
// System Program's u32 LE) — this is the Solana Token program's bincode convention.
//
// ATA PDA derivation uses the documented ProgramDerivedAddress algorithm: sha256 over
// (seeds ++ programId ++ 'ProgramDerivedAddress'), rejecting any result that decodes to a valid
// ed25519 point, iterating the bump seed 255→0. The on-curve check uses noble's ExtendedPoint.fromHex
// — the SAME primitive @solana/web3.js v1 delegates to, so the derivation matches exactly.

import { ed25519 } from '@noble/curves/ed25519';
import { sha256 } from '@noble/hashes/sha256';
import bs58 from 'bs58';
import {
  base58Decode32,
  encodeU64LE,
  assembleMessage,
  buildMemoInstruction,
  solreqMemoData,
  type Instruction,
} from './tx';
import { encodeSolReq, type SolReqV2 } from './qr';
import { SYSTEM_PROGRAM_ADDRESS } from './constants';

/** SPL Token Program (the legacy TokenkegQ program that USDC/SPL fungibles use). */
export const TOKEN_PROGRAM_ADDRESS = 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA';
/** Associated Token Account Program (creates ATAs; not directly invoked here but documented). */
export const ASSOCIATED_TOKEN_PROGRAM_ADDRESS = 'ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL';
/** USDC mainnet mint + decimals. Canonical home is the token registry (`tokens.ts`); these
 *  re-exports keep every existing import (and the golden-vector bytes) unmoved. */
export {USDC_MINT_ADDRESS, USDC_DECIMALS} from './tokens';
/** Rent sysvar (passed readonly to create-ATA; the chain charges real rent regardless). */
export const RENT_SYSVAR_ADDRESS = 'SysvarRent111111111111111111111111111111111';
/** Canonical mainnet rent for a 165-byte SPL token account (lamports). An ESTIMATE for display +
 *  friendly pre-checks — the chain enforces the real value at execution; never trust-bearing. */
export const SOL_ATA_RENT_LAMPORTS = 2_039_280n;
/** One Solana transaction fee (lamports per signature — the long-stable default). */
export const SOL_FEE_LAMPORTS = 5_000n;
/** Minimum SOL a wallet needs to create its USDC ATA (rent + one fee). */
export const SOL_ATA_SETUP_MIN_LAMPORTS = SOL_ATA_RENT_LAMPORTS + SOL_FEE_LAMPORTS;

/** Net the one-signature network fee out of a payee-quoted NATIVE-SOL request price — founder rule
 *  2026-09-12: "if price of something is $1, the customer pays exactly $1 — the merchant pays the
 *  fees". The wire `amt` a native-SOL request carries is `price − SOL_FEE_LAMPORTS` (the SOL twin
 *  of the dpay till's `amount_raw = price − fee`, till.rs:348), so the payer's displayed total
 *  (wire amount + fee) IS the typed price and the fee lands payee-side. The netting belongs to the
 *  REQUEST BUILDER, never the signer: every downstream verify (verifySolPayment) is byte-exact
 *  against the canonical rebuild of the request, so the payer cannot change the amount at sign
 *  time — and cannot repair a request that was never netted either.
 *
 *  SPL tokens (USDC, EURC, …) are the ONE documented exception and are NOT netted: their fee is
 *  separate-asset SOL gas, physically impossible to subtract from a token amount (the uniform-IA
 *  divergence rule allows exactly this and nothing else). An SPL request carries the typed token
 *  amount verbatim.
 *
 *  `priceLamports` is a decimal digit-string of raw lamports (what `toUnits` yields). Returns the
 *  netted wire lamports as a digit-string, or null when the price is ≤ SOL_FEE_LAMPORTS — a price
 *  the fee would swallow, which the request builder must REFUSE (netting would zero or invert the
 *  request: there is no honest wire amount left). */
export function netSolWireLamports(priceLamports: string): string | null {
  const price = BigInt(priceLamports);
  return price > SOL_FEE_LAMPORTS ? (price - SOL_FEE_LAMPORTS).toString() : null;
}

// ── Account LAYOUTS (read side) ────────────────────────────────────────────────────────────────
// The balance poll reads accounts in one `getMultipleAccounts` call and decodes the bytes here,
// instead of asking the node to parse one account per request. Every offset below is pinned
// against real mainnet bytes in `__tests__/solana-account-decode.test.ts`: the amount this decodes
// is checked against `getTokenAccountBalance`'s answer for the SAME account, and the decimals
// against the same response's `decimals`. Nothing here is from memory.
//
// SPL Token ACCOUNT (165 bytes): mint[32] ++ owner[32] ++ amount u64LE ++ … (delegate, state,
// is_native, delegated_amount, close_authority follow; this wallet reads none of them, and a field
// nothing reads is a field nothing can be wrong about).
/** Exact byte length of an SPL Token account. A shorter or longer account is not one. */
export const SPL_TOKEN_ACCOUNT_LEN = 165;
const TOKEN_ACCOUNT_AMOUNT_OFFSET = 64;
// SPL Token MINT (82 bytes): mint_authority COption<Pubkey>[36] ++ supply u64LE[8] ++ decimals u8.
/** Exact byte length of an SPL Token mint account. */
export const SPL_MINT_ACCOUNT_LEN = 82;
const MINT_DECIMALS_OFFSET = 44;

/** Read the raw token amount out of an SPL token account, as an exact `bigint` (money-critical:
 *  never through JS `number`, which loses precision above 2^53).
 *
 *  `expectedMint` is the mint the caller DERIVED this account's address from; the account states
 *  its own mint in its first 32 bytes and the two must agree. They can only disagree if the
 *  address, the derivation or the response mapping is wrong — none of which may be answered with
 *  a number. Every refusal throws with a reason; a caller turns that into an honest "couldn't
 *  read", never a zero. */
export function decodeSplTokenAmount(data: Uint8Array, expectedMint: string): bigint {
  if (data.length !== SPL_TOKEN_ACCOUNT_LEN) {
    throw new Error(`spl token account is ${data.length} bytes, expected exactly ${SPL_TOKEN_ACCOUNT_LEN} bytes`);
  }
  const mint = bs58.encode(data.subarray(0, 32));
  if (mint !== expectedMint) {
    throw new Error(`spl token account holds mint ${mint}, expected ${expectedMint}`);
  }
  let amount = 0n;
  for (let i = 7; i >= 0; i--) {
    amount = (amount << 8n) | BigInt(data[TOKEN_ACCOUNT_AMOUNT_OFFSET + i]);
  }
  return amount;
}

/** Read a mint's `decimals`. The CHAIN's own answer for the scale a token is counted in — the same
 *  fact `getTokenAccountBalance` used to return alongside the amount, read from the same source. */
export function decodeSplMintDecimals(data: Uint8Array): number {
  if (data.length !== SPL_MINT_ACCOUNT_LEN) {
    throw new Error(`spl mint account is ${data.length} bytes, expected exactly ${SPL_MINT_ACCOUNT_LEN} bytes`);
  }
  return data[MINT_DECIMALS_OFFSET];
}

const TOKEN_PROGRAM_BYTES = base58Decode32(TOKEN_PROGRAM_ADDRESS);
const ASSOCIATED_TOKEN_PROGRAM_BYTES = base58Decode32(ASSOCIATED_TOKEN_PROGRAM_ADDRESS);
const PDA_MARKER = new TextEncoder().encode('ProgramDerivedAddress');

// SPL Token `transfer` instruction index — a SINGLE u8 (Token program bincode convention), not u32.
const IX_TOKEN_TRANSFER = 3;

/**
 * Derive a Program-Derived Address: sha256(seeds ++ programId ++ 'ProgramDerivedAddress'). Throws if
 * the result decodes to a valid ed25519 point (PDAs must fall OFF the curve). Matches
 * @solana/web3.js PublicKey.createProgramAddressSync exactly (same sha256, same on-curve check).
 */
function createProgramAddress(seeds: Uint8Array[], programId: Uint8Array): Uint8Array {
  const parts: Uint8Array[] = [];
  for (const s of seeds) {
    if (s.length > 32) throw new Error('max seed length exceeded');
    parts.push(s);
  }
  parts.push(programId);
  parts.push(PDA_MARKER);
  let total = 0;
  for (const p of parts) total += p.length;
  const buf = new Uint8Array(total);
  let off = 0;
  for (const p of parts) { buf.set(p, off); off += p.length; }
  const hash = sha256(buf);
  // A PDA must NOT be a valid ed25519 public key. fromHex throws on an off-curve/incompliant point.
  try {
    ed25519.ExtendedPoint.fromHex(hash);
  } catch {
    return hash; // off-curve → valid PDA
  }
  throw new Error('invalid seeds: address must fall off the curve');
}

/**
 * Find the canonical PDA: iterate the bump seed 255→0 and return the first that derives off-curve.
 * Mirrors @solana/web3.js PublicKey.findProgramAddressSync. Returns {pubkey, bump}.
 */
function findProgramAddress(
  seeds: Uint8Array[],
  programId: Uint8Array,
): { pubkey: Uint8Array; bump: number } {
  for (let bump = 255; bump > 0; bump--) {
    try {
      const pubkey = createProgramAddress([...seeds, new Uint8Array([bump])], programId);
      return { pubkey, bump };
    } catch {
      continue;
    }
  }
  throw new Error('unable to find a viable program address nonce');
}

/**
 * Derive the Associated Token Account address for (wallet, mint) under the Token Program.
 * Seeds = [wallet(32), TOKEN_PROGRAM_ID(32), mint(32)], derived under the ASSOCIATED TOKEN PROGRAM
 * (NOT the Token Program itself — a common gotcha). Matches @solana/spl-token
 * getAssociatedTokenAddressSync exactly.
 */
export function deriveAta(walletAddress: string, mintAddress: string): Uint8Array {
  const wallet = base58Decode32(walletAddress);
  const mint = base58Decode32(mintAddress);
  return findProgramAddress(
    [wallet, TOKEN_PROGRAM_BYTES, mint],
    ASSOCIATED_TOKEN_PROGRAM_BYTES,
  ).pubkey;
}

// Associated Token Account Program `createIdempotent` instruction index — a SINGLE u8. Unlike
// `create` (0), it succeeds as a no-op when the ATA already exists — safe against TOCTOU races
// and safe to bundle into a send unconditionally-checked.
const IX_ATA_CREATE_IDEMPOTENT = 1;

/**
 * Build an Associated Token Account Program `createIdempotent` instruction: creates the canonical
 * ATA for (owner, mint) if (and only if) it does not already exist, funded by `payer`. Accounts
 * (matching @solana/spl-token createAssociatedTokenAccountInstruction):
 *   [0] payer          — writable, signer (pays the one-time account rent + fees)
 *   [1] ata            — writable, nonsigner (the account being created)
 *   [2] owner          — readonly, nonsigner (the wallet the ATA belongs to)
 *   [3] mint           — readonly, nonsigner
 *   [4] system program — readonly, nonsigner
 *   [5] token program  — readonly, nonsigner
 *   [6] rent sysvar    — readonly, nonsigner
 * Data: u8(1). Honest by construction: an existing ATA is left untouched (no rent re-charged).
 */
export function buildCreateAtaIdempotentInstruction(
  payer: Uint8Array,
  ata: Uint8Array,
  owner: Uint8Array,
  mint: Uint8Array,
): Instruction {
  return {
    programId: ASSOCIATED_TOKEN_PROGRAM_BYTES,
    keys: [
      {pubkey: payer, signer: true, writable: true},
      {pubkey: ata, signer: false, writable: true},
      {pubkey: owner, signer: false, writable: false},
      {pubkey: mint, signer: false, writable: false},
      {pubkey: base58Decode32(SYSTEM_PROGRAM_ADDRESS), signer: false, writable: false},
      {pubkey: TOKEN_PROGRAM_BYTES, signer: false, writable: false},
      {pubkey: base58Decode32(RENT_SYSVAR_ADDRESS), signer: false, writable: false},
    ],
    data: new Uint8Array([IX_ATA_CREATE_IDEMPOTENT]),
  };
}

/**
 * Build a Token Program `transfer` instruction (raw form). The owner authorizes moving `amount` raw
 * units from the source token account to the destination token account. Accounts:
 *   [0] source  — writable, nonsigner
 *   [1] dest    — writable, nonsigner
 *   [2] owner   — readonly, signer (authorizes the debit)
 * Data: u8(3) || u64 LE amount. The Token program discriminator is a single byte (not u32).
 */
export function buildSplTransferInstruction(
  sourceAta: Uint8Array,
  destAta: Uint8Array,
  owner: Uint8Array,
  amount: bigint,
): Instruction {
  if (amount < 0n) throw new Error('amount must be non-negative');
  const data: number[] = [];
  data.push(IX_TOKEN_TRANSFER); // u8 discriminator
  encodeU64LE(data, amount);
  return {
    programId: TOKEN_PROGRAM_BYTES,
    keys: [
      { pubkey: sourceAta, signer: false, writable: true },
      { pubkey: destAta, signer: false, writable: true },
      { pubkey: owner, signer: true, writable: false },
    ],
    data: new Uint8Array(data),
  };
}

// ============================================================================
// Canonical recent-blockhash v2 USDC construction: {Memo(ix0), Token.transferChecked(ix1)}.
// ============================================================================

// SPL Token `transferChecked` instruction index — a SINGLE u8 (Token program bincode convention).
const IX_TOKEN_TRANSFER_CHECKED = 12;

/**
 * Build a Token Program `transferChecked` instruction. Commits to the mint + decimals (unlike raw
 * `transfer`), preventing a wrong-decimals or wrong-mint token from satisfying the payment. Accounts
 * (matching @solana/spl-token createTransferCheckedInstruction):
 *   [0] source   — writable, nonsigner
 *   [1] mint     — readonly, nonsigner
 *   [2] dest     — writable, nonsigner
 *   [3] owner    — readonly, signer (authorizes the debit)
 * Data: u8(12) || u64 LE amount || u8 decimals.
 *
 * `additionalKeys` are extra READONLY non-signing account references — the Solana Pay `reference`
 * keys, appended after the owner exactly the way the solana-pay SDK appends them, so a merchant can
 * match the transfer to their sale. The Token Program ignores them. Default `[]` keeps every
 * existing caller byte-identical.
 */
export function buildTransferCheckedInstruction(
  sourceAta: Uint8Array,
  mint: Uint8Array,
  destAta: Uint8Array,
  owner: Uint8Array,
  amount: bigint,
  decimals: number,
  additionalKeys: Uint8Array[] = [],
): Instruction {
  if (amount < 0n) throw new Error('amount must be non-negative');
  const data: number[] = [];
  data.push(IX_TOKEN_TRANSFER_CHECKED);
  encodeU64LE(data, amount);
  data.push(decimals & 0xff);
  return {
    programId: TOKEN_PROGRAM_BYTES,
    keys: [
      { pubkey: sourceAta, signer: false, writable: true },
      { pubkey: mint, signer: false, writable: false },
      { pubkey: destAta, signer: false, writable: true },
      { pubkey: owner, signer: true, writable: false },
      ...additionalKeys.map(pubkey => ({ pubkey, signer: false, writable: false })),
    ],
    data: new Uint8Array(data),
  };
}

/**
 * Build the canonical SPL-token v2 message: {Memo(ix0), Token.transferChecked(ix1)} with
 * recentBlockhash = request.bh. The memo binds every request field; transferChecked commits to the
 * source ATA, mint, destination ATA, owner (payer), amount, and `decimals` (the token's own — the
 * caller supplies the registry value; USDC callers pass `USDC_DECIMALS`, keeping the historical
 * bytes identical). The payer is the sole signer and fee payer; the source ATA is the payer's
 * canonical ATA for the request mint.
 */
export function buildCanonicalSplMessage(payer: Uint8Array, request: SolReqV2, decimals: number): Uint8Array {
  if (request.mint === null || request.toAta === null) {
    throw new Error('buildCanonicalSplMessage: mint and toAta are required for an SPL token');
  }
  const canonicalUri = encodeSolReq(request);
  const memoIx = buildMemoInstruction(solreqMemoData(canonicalUri));
  const sourceAta = deriveAta(bs58.encode(payer), request.mint);
  const mint = base58Decode32(request.mint);
  const destAta = base58Decode32(request.toAta);
  const transferCheckedIx = buildTransferCheckedInstruction(
    sourceAta,
    mint,
    destAta,
    payer,
    BigInt(request.amt),
    decimals,
  );
  return assembleMessage(payer, [memoIx, transferCheckedIx], base58Decode32(request.bh));
}
